static void setting_secondary_forward_key(uint32_t key)
{
    lv_obj_t *active_screen = lv_scr_act();
    if (active_screen != NULL) {
        lv_event_send(active_screen, LV_EVENT_KEY, (void *)(uintptr_t)key);
    }
}

static void setting_secondary_screen_event_cb(lv_event_t *e)
{
    switch (lv_event_get_code(e)) {
        case LV_EVENT_SCREEN_LOADED:
            ui_StatusBar_show(false);
            setting_secondary_refresh();
            break;
        case LV_EVENT_SCREEN_UNLOADED:
            ui_StatusBar_show(true);
            break;
        default:
            break;
    }
}

static void setting_secondary_handle_key(int32_t key)
{
    if (key == LV_KEY_UP) {
        s_setting_focus = (uint8_t)((s_setting_focus == 0) ? (SETTING_ITEM_COUNT - 1) : (s_setting_focus - 1));
        setting_secondary_refresh();
        return;
    }

    if (key == LV_KEY_DOWN) {
        s_setting_focus = (uint8_t)((s_setting_focus + 1) % SETTING_ITEM_COUNT);
        setting_secondary_refresh();
        return;
    }

    if (key == LV_KEY_ENTER) {
        setting_secondary_refresh();
        return;
    }

    if (key == LV_KEY_ESC) {
        ui_set_active_screen_tag(UI_SCREEN_SETTING);
        _ui_screen_change(&ui_SettingScreen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_SettingScreen_screen_init);
        lv_refr_now(NULL);
        return;
    }

    if ((key == LV_KEY_LEFT || key == LV_KEY_RIGHT) &&
        setting_secondary_adjust_value((setting_item_id_t)s_setting_focus, key == LV_KEY_RIGHT ? 1 : -1)) {
        setting_secondary_schedule_apply();
        return;
    }

    setting_secondary_refresh();
}

void ui_event_SettingScreenSecondary(lv_event_t * e)
{
    const lv_event_code_t event_code = lv_event_get_code(e);
    const uintptr_t key = (uintptr_t)lv_event_get_param(e);

    if (event_code == LV_EVENT_KEY) {
        setting_secondary_handle_key((int32_t)key);
    }
}

