void ui_SettingScreenSecondary_screen_destroy(void)
{
    setting_secondary_cancel_timer();

    if (ui_SettingScreenSecondary != NULL) {
        lv_obj_del(ui_SettingScreenSecondary);
    }

    ui_SettingScreenSecondary = NULL;
    ui_SettingSecondaryButtonLeft = NULL;
    ui_SettingSecondaryButtonRight = NULL;
    ui_SettingSecondaryButtonEnter = NULL;
    ui_SettingSecondaryButtonExit = NULL;
    ui_SettingSecondaryHeader = NULL;
    ui_SettingSecondaryTitle = NULL;
    ui_SettingSecondaryStatus = NULL;
    ui_SettingSecondaryPanel = NULL;
    ui_SettingSecondaryFooter = NULL;
    ui_SettingSecondaryHintLeft = NULL;
    ui_SettingSecondaryHintCenter = NULL;
    ui_SettingSecondaryHintRight = NULL;

    memset(ui_SettingSecondaryRows, 0, sizeof(ui_SettingSecondaryRows));
    memset(ui_SettingSecondaryNames, 0, sizeof(ui_SettingSecondaryNames));
    memset(ui_SettingSecondaryValues, 0, sizeof(ui_SettingSecondaryValues));
}